// Simulación en Node: no hay `document` fuera del navegador, así que esta
// clase imita la forma mínima de un nodo del DOM para poder ejecutar el
// ejemplo. En un navegador real, document.getElementById('submit-btn')
// devolvería el nodo directamente en vez de construirlo a mano.
class FakeElement {
  constructor(tagName, id) {
    this.tagName = tagName;
    this.id = id;
    this.classList = new Set();
    this.children = [];
    this.textContent = '';
  }
  appendChild(child) {
    this.children.push(child);
    return child;
  }
  querySelector(selector) {
    return this.children.find((c) => selector === `#${c.id}`) || null;
  }
  remove(cls) {
    this.classList.delete(cls);
  }
}

const app = new FakeElement('div', 'app');
const button = new FakeElement('button', 'submit-btn');
button.textContent = 'Enviar';
button.classList.add('btn');
app.appendChild(button);

const found = app.querySelector('#submit-btn');
console.log(found.textContent);
found.classList.add('btn-primary');
console.log([...found.classList]);
found.remove('btn');
console.log([...found.classList]);
console.log(app.children.length);
